<div class="admin-page-head"><div><span class="eyebrow">کنترل عملیات</span><h1>مالی و انبار</h1><p>گردش ثبت‌شده سفارش‌ها و تطبیق موجودی قابل فروش</p></div></div><div class="metric-grid report-metrics"><?php foreach(array('receipts'=>'دریافت ثبت‌شده','refunds'=>'بازپرداخت','net'=>'خالص دریافتی') as $key=>$title): ?><div class="metric"><small><?= $title ?></small><strong><?= Money::format($totals[$key]) ?></strong></div><?php endforeach; ?></div>
<section class="panel"><h2>صحت موجودی انبار</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>محصول</th><th>موجودی قابل فروش</th><th>جمع گردش انبار</th><th>تطبیق</th></tr></thead><tbody><?php foreach($stock as $p): ?><tr><td><?= CHtml::encode($p['title']) ?></td><td><?= number_format($p['stock']) ?></td><td><?= number_format($p['ledger']) ?></td><td><span class="status <?= $p['stock']==$p['ledger']?'status-paid':'status-cancelled' ?>"><?= $p['stock']==$p['ledger']?'مطابق':'نیاز به بررسی' ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h2>گردش مالی <small class="muted">۱۰۰ رویداد اخیر</small></h2><div class="table-wrap"><table class="data-table"><thead><tr><th>سفارش</th><th>نوع</th><th>مبلغ</th><th>تاریخ</th></tr></thead><tbody><?php foreach($entries as $e): ?><tr><td><?= CHtml::link(CHtml::encode($e['order_number']),array('adminOrder/view','id'=>$e['order_id']),array('data-pjax'=>'1')) ?></td><td><?= $e['kind']==='receipt'?'دریافت':'بازپرداخت' ?></td><td dir="ltr"><?= Money::format($e['amount']) ?></td><td><?= CHtml::encode($e['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$entries): ?><tr><td colspan="4">هنوز دریافتی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><h2>گردش انبار <small class="muted">۱۰۰ رویداد اخیر</small></h2><div class="table-wrap"><table class="data-table"><thead><tr><th>کالا</th><th>تغییر</th><th>علت</th><th>سفارش</th><th>تاریخ</th></tr></thead><tbody><?php $labels=array('opening'=>'موجودی اولیه','adjustment'=>'اصلاح موجودی','reserve'=>'رزرو','returned'=>'مرجوعی','expired'=>'انقضای رزرو','cancelled'=>'لغو');foreach($movements as $m): ?><tr><td><?= CHtml::encode($m['title']) ?></td><td dir="ltr"><?= sprintf('%+d',$m['quantity']) ?></td><td><?= CHtml::encode(isset($labels[$m['kind']])?$labels[$m['kind']]:$m['kind']) ?></td><td><?= CHtml::encode($m['order_number']?:'—') ?></td><td><?= CHtml::encode($m['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><p class="muted note">ثبت پرداخت در این پنل دستی است؛ این گزارش به درگاه بانکی متصل نیست.</p>
